t.script:
//
(function () {
  var btn = document.getElementById('acPayBtn');
  var errEl = document.getElementById('acPayErr');
  var dataEl = document.getElementById('acCheckoutData');
  var meta = document.getElementById('acRzpMeta');
  var verifyUrl = (meta && meta.getAttribute('data-verify-url')) || '';
  var autoOpen = meta && meta.getAttribute('data-auto-open') === '1';
  var opening = false;

  function showErr(msg) {
    if (!errEl) { alert(msg); return; }
    errEl.style.display = 'block';
    errEl.textContent = msg;
  }

  function getCheckout() {
    try { return JSON.parse((dataEl && dataEl.textContent) || '{}'); }
    catch (e) { return null; }
  }

  function loadRazorpay(cb) {
    if (window.Razorpay) { cb(null); return; }
    var existing = document.querySelector('script[data-ac-rzp="1"]');
    if (existing) {
      existing.addEventListener('load', function () { cb(null); });
      existing.addEventListener('error', function () { cb(new Error('load failed')); });
      return;
    }
    var s = document.createElement('script');
    s.src = 'https://checkout.razorpay.com/v1/checkout.js';
    s.async = true;
    s.setAttribute('data-ac-rzp', '1');
    s.onload = function () { cb(null); };
    s.onerror = function () { cb(new Error('load failed')); };
    document.head.appendChild(s);
  }

  function setBtn(label, disabled) {
    if (!btn) return;
    btn.disabled = !!disabled;
    var txt = btn.querySelector('.ac-rzp-pay-btn-txt');
    if (txt) txt.textContent = label;
    else btn.textContent = label;
  }

  function verifyPayment(checkout, response) {
    setBtn('Verifying…', true);
    fetch(verifyUrl, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        jsonrpc: '2.0',
        method: 'call',
        params: {
          token: checkout.transaction_token,
          razorpay_payment_id: response.razorpay_payment_id,
          razorpay_order_id: response.razorpay_order_id,
          razorpay_signature: response.razorpay_signature
        }
      })
    }).then(function (r) { return r.json(); })
      .then(function (data) {
        var res = (data && data.result) ? data.result : data;
        if (res && res.ok && res.redirect) {
          window.location.href = res.redirect;
        } else {
          alert((res && res.error) || 'Payment verification failed');
          setBtn(btn.getAttribute('data-label') || 'Pay with Razorpay', false);
          opening = false;
        }
      }).catch(function () {
        alert('Network error while verifying payment');
        setBtn(btn.getAttribute('data-label') || 'Pay with Razorpay', false);
        opening = false;
      });
  }

  function openCheckout() {
    if (!btn || opening) return;
    var checkout = getCheckout();
    if (!checkout || !checkout.key_id || !checkout.order_id) {
      showErr('Payment session is incomplete. Please submit registration again.');
      return;
    }
    opening = true;
    if (errEl) errEl.style.display = 'none';
    setBtn('Opening Razorpay…', true);

    loadRazorpay(function (err) {
      if (err || !window.Razorpay) {
        showErr('Could not load Razorpay. Allow checkout.razorpay.com, disable ad-block, then retry.');
        setBtn(btn.getAttribute('data-label') || 'Pay with Razorpay', false);
        opening = false;
        return;
      }
      try {
        var rzp = new window.Razorpay({
          key: checkout.key_id,
          amount: checkout.amount,
          currency: checkout.currency || 'INR',
          name: checkout.name || 'AuctionChamp',
          description: checkout.description || 'Registration',
          order_id: checkout.order_id,
          prefill: checkout.prefill || {},
          theme: { color: '#1a3a6e' },
          modal: {
            ondismiss: function () {
              setBtn(btn.getAttribute('data-label') || 'Pay with Razorpay', false);
              opening = false;
            }
          },
          handler: function (response) {
            verifyPayment(checkout, response);
          }
        });
        rzp.on('payment.failed', function (resp) {
          var msg = (resp && resp.error && (resp.error.description || resp.error.reason)) || 'Payment failed';
          showErr(msg);
          setBtn(btn.getAttribute('data-label') || 'Pay with Razorpay', false);
          opening = false;
        });
        rzp.open();
        setBtn(btn.getAttribute('data-label') || 'Pay with Razorpay', false);
        opening = false;
      } catch (e) {
        showErr((e && e.message) || 'Unable to open Razorpay checkout.');
        setBtn(btn.getAttribute('data-label') || 'Pay with Razorpay', false);
        opening = false;
      }
    });
  }

  if (btn) {
    var initial = (btn.querySelector('.ac-rzp-pay-btn-txt') || btn).textContent || 'Pay with Razorpay';
    btn.setAttribute('data-label', initial.trim());
    btn.addEventListener('click', function (ev) {
      ev.preventDefault();
      openCheckout();
    });
    if (autoOpen) {
      setTimeout(openCheckout, 350);
    }
  }
})();
//
